begin;
-- Reverse references preserve retained history separately from live consumers.
create table app_private.combat_content_references (
 source_key text not null references app_private.combat_content_records(content_key),
 version_key text not null,
 version_id uuid references app_private.combat_content_versions(id),
 target_key text not null,
 primary key(source_key,version_key,target_key),
 check((version_key='draft' and version_id is null) or version_key=version_id::text)
);
create index combat_content_references_target_idx on app_private.combat_content_references(target_key,source_key);
alter table app_private.combat_content_references enable row level security;
revoke all on app_private.combat_content_references from public,anon,authenticated,service_role;
create table app_private.combat_content_builtin_selections (
 kind text not null check(kind in ('builtin-essence-selection','builtin-resonance-selection')),
 selection_key text not null,
 content_key text not null references app_private.combat_content_records(content_key),
 primary key(kind,selection_key)
);
create index combat_content_builtin_selections_target_idx on app_private.combat_content_builtin_selections(content_key);
alter table app_private.combat_content_builtin_selections enable row level security;
revoke all on app_private.combat_content_builtin_selections from public,anon,authenticated,service_role;
