create function app_private.content_reference_targets_v1(d jsonb)
returns setof text language plpgsql immutable set search_path='' as $$
declare pending jsonb[]:=array[d]; current jsonb; entry record; child jsonb; visited integer:=0;
begin
 while cardinality(pending)>0 loop
  current:=pending[cardinality(pending)]; pending:=pending[1:cardinality(pending)-1]; visited:=visited+1;
  if visited>32768 then raise exception using errcode='22023',message='COMBAT_CONTENT_REFERENCE_BUDGET'; end if;
  if jsonb_typeof(current)='object' then
   for entry in select * from jsonb_each(current) loop
    if entry.key in ('sourceDisciplineId','skillId','abilityId','statusId','effectProfileId') and jsonb_typeof(entry.value)='string' then return next entry.value#>>'{}'; end if;
    if entry.key in ('disciplinePair','linkedSkills','statusIds') and jsonb_typeof(entry.value)='array' then
     for child in select value from jsonb_array_elements(entry.value) loop
      if jsonb_typeof(child)='string' then return next child#>>'{}'; end if;
     end loop;
    end if;
    if jsonb_typeof(entry.value) in ('object','array') then pending:=array_append(pending,entry.value); end if;
   end loop;
  elsif jsonb_typeof(current)='array' then
   for child in select value from jsonb_array_elements(current) loop
    if jsonb_typeof(child) in ('object','array') then pending:=array_append(pending,child); end if;
   end loop;
  end if;
 end loop;
end; $$;

insert into app_private.combat_content_references
 select distinct d.content_key,'draft',null::uuid,t from app_private.combat_content_drafts d cross join lateral app_private.content_reference_targets_v1(d.definition) t;
insert into app_private.combat_content_references
 select distinct v.content_key,v.id::text,v.id,t from app_private.combat_content_versions v cross join lateral app_private.content_reference_targets_v1(v.definition) t;
create function app_private.index_content_references_v1()
returns trigger language plpgsql security definer set search_path='' as $$
declare target text; version_key text; version_id uuid;
begin
 if tg_table_name='combat_content_drafts' then
  delete from app_private.combat_content_references where source_key=old.content_key and combat_content_references.version_key='draft';
  if tg_op='DELETE' then return old; end if;
  version_key:='draft'; version_id:=null;
 else version_key:=new.id::text; version_id:=new.id; end if;
 for target in select distinct t from app_private.content_reference_targets_v1(new.definition) t loop
  if exists(select 1 from app_private.combat_content_records r where r.content_key=target and r.lifecycle='archived') then raise exception using errcode='22023',message='COMBAT_CONTENT_ARCHIVED'; end if;
  insert into app_private.combat_content_references values(new.content_key,version_key,version_id,target);
 end loop;
 return new;
end; $$;
create trigger content_reference_index after insert or update or delete on app_private.combat_content_drafts for each row execute function app_private.index_content_references_v1();
create trigger content_reference_index after insert on app_private.combat_content_versions for each row execute function app_private.index_content_references_v1();

create function app_private.combat_content_blockers_v1(p_key text)
returns table(kind text,key text) language sql stable security definer set search_path='' as $$
 select 'content-link',l.parent_key from app_private.combat_content_links l join app_private.combat_content_records r on r.content_key=l.parent_key where l.child_key=p_key and r.lifecycle<>'archived'
 union all select b.kind,b.selection_key from app_private.combat_content_builtin_selections b where b.content_key=p_key
 union all select 'phase4-catalogue',skill_id from app_private.phase4_skill_catalog where skill_id=p_key or discipline_id=p_key
 union all select 'earned-skill',character_id::text from app_private.character_skill_unlocks where skill_id=p_key or source_discipline_id=p_key
 union all select 'equipped-skill',character_id::text from app_private.character_build_discipline_skills where skill_id=p_key or source_discipline_id=p_key
 union all select 'saved-loadout',character_id::text||':'||slot_index from app_private.character_saved_build_loadouts l where primary_discipline_id=p_key or secondary_discipline_id=p_key or exists(select 1 from jsonb_array_elements(l.discipline_skills) s where s->>'skillId'=p_key or s->>'sourceDisciplineId'=p_key)
 union all select 'definition-draft',f.source_key from app_private.combat_content_references f join app_private.combat_content_records r on r.content_key=f.source_key where f.target_key=p_key and f.version_key='draft' and r.lifecycle<>'archived' and f.source_key<>p_key
 union all select 'definition-current',f.source_key from app_private.combat_content_references f join app_private.combat_content_publications p on p.version_id=f.version_id where f.target_key=p_key and f.source_key<>p_key;
$$;
create function app_private.combat_content_all_uses_v1(p_key text)
returns table(kind text,key text,blocking boolean) language sql stable security definer set search_path='' as $$
 select b.kind,b.key,true from app_private.combat_content_blockers_v1(p_key) b
 union all select 'definition-history',f.source_key||'@'||v.content_version,false from app_private.combat_content_references f join app_private.combat_content_versions v on v.id=f.version_id where f.target_key=p_key and not exists(select 1 from app_private.combat_content_publications p where p.version_id=f.version_id);
$$;
create or replace function app_private.combat_content_used_by_v1(p_key text)
returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(x),'[]') from (select * from app_private.combat_content_all_uses_v1(p_key) order by blocking desc,kind,key limit 100) x;
$$;
revoke all on function app_private.content_reference_targets_v1(jsonb),app_private.index_content_references_v1(),app_private.combat_content_blockers_v1(text),app_private.combat_content_all_uses_v1(text) from public,anon,authenticated,service_role;

create function app_private.bound_content_links_v1()
returns trigger language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from app_private.combat_content_links where parent_key=new.parent_key and child_key=new.child_key)
 and (select count(*) from app_private.combat_content_links where parent_key=new.parent_key)>=256 then raise exception using errcode='22023',message='COMBAT_CONTENT_LINK_LIMIT'; end if;
 return new;
end; $$;
create trigger content_links_bound before insert on app_private.combat_content_links for each row execute function app_private.bound_content_links_v1();
